diff --git a/src/ui/scroll.c b/src/ui/scroll.c
index 810ad9c..e8836cf 100644
--- a/src/ui/scroll.c
+++ b/src/ui/scroll.c
@@ -1,3 +1,4 @@
+#include <math.h>
 #include <stdbool.h>
 #include <stdlib.h>
 #include "stb_ds.h"
@@ -42,3 +43,22 @@ void scroll_reset(void)
     offsets = NULL;
     map_initialized = false;
 }
+
+int scroll_max_offset(int viewport_height, int content_height)
+{
+    int max_offset = content_height - viewport_height;
+    return max_offset < 0 ? 0 : max_offset;
+}
+
+int scroll_momentum_step(int offset, int max_offset, float *velocity, float dt)
+{
+    int next = offset + (int)roundf(*velocity * dt);
+    if (next <= 0) {
+        next = 0;
+        *velocity = 0.0f;
+    } else if (next >= max_offset) {
+        next = max_offset;
+        *velocity = 0.0f;
+    }
+    return next;
+}

diff --git a/src/ui/scroll.h b/src/ui/scroll.h
index 1413b5e..f9afc27 100644
--- a/src/ui/scroll.h
+++ b/src/ui/scroll.h
@@ -10,4 +10,11 @@ void scroll_set_offset(const char *id, int offset);
 /* Drop all stored offsets (e.g. when the Deck App runtime restarts). */
 void scroll_reset(void);

+/* Largest offset that keeps the viewport inside the content; 0 when the content fits. */
+int scroll_max_offset(int viewport_height, int content_height);
+
+/* Advances a touch momentum scroll by one frame and returns the next offset, clamped to [0, max_offset].
+ * Stops the momentum (zeroes *velocity, in px/s) when it reaches either end. Friction is the caller's. */
+int scroll_momentum_step(int offset, int max_offset, float *velocity, float dt);
+
 #endif /* SCROLL_H */

